## Setup commands that worked, in order
```bash
npx --yes create-next-app@16 app --ts --app --src-dir --tailwind --eslint --no-turbopack --import-alias "@/*" --use-npm --yes
cd app
npx supabase@2.122.0 init && sed -i 's/^project_id = "app"/project_id = "<name>"/' supabase/config.toml
npx supabase@2.122.0 start            # run in background; continue with installs meanwhile
echo 'node-options=--experimental-websocket' > .npmrc     # GOTCHA 1, do before anything runs supabase-js
npm i @prisma/client@7.10.1 @prisma/adapter-pg@7.10.1 pg @supabase/ssr @supabase/supabase-js
npm i -D prisma@7.10.1 @types/pg dotenv
npm i -D vitest@4 --legacy-peer-deps                     # GOTCHA 2 + 3
npx prisma init --datasource-provider postgresql         # writes prisma7.config.ts, prisma/schema.prisma, .env
npx --yes shadcn@latest init -y -d                       # also creates components/ui/button.tsx
npx shadcn@latest add button -y
npm pkg set scripts.postinstall="prisma generate" scripts.test="vitest run" scripts.typecheck="tsc --noEmit"
# write .env from supabase (overwrite the prisma placeholder):
eval "$(npx supabase status -o env 2>/dev/null | grep -E '^(API_URL|ANON_KEY|SERVICE_ROLE_KEY|DB_URL)=')"
printf 'NEXT_PUBLIC_SUPABASE_URL=%s\nNEXT_PUBLIC_SUPABASE_ANON_KEY=%s\nSUPABASE_SERVICE_ROLE_KEY=%s\nDATABASE_URL=%s\n' "$API_URL" "$ANON_KEY" "$SERVICE_ROLE_KEY" "$DB_URL" > .env
# add migration supabase/migrations/20261024000001_init.sql + supabase/seed.sql, then:
npx supabase db reset                 # if it says DbSetupError "exit 1" right after start: just rerun
# add schemas = ["auth","public"] to datasource, then:
npx prisma db pull && npx prisma generate
npx tsc --noEmit && npx eslint . --max-warnings=0 && npm run build
for tz in UTC Asia/Dubai America/New_York; do TZ=$tz npx vitest run; done
npx supabase stop
