// tests/global-setup.ts
import { spawn, type ChildProcess } from "node:child_process";
const PORT = 3100, BASE = `http://localhost:${PORT}`;
let child: ChildProcess | undefined;
const up = () => fetch(`${BASE}/api/me`, { signal: AbortSignal.timeout(2000) }).then(() => true, () => false);
export async function setup() {
  process.env.TEST_BASE_URL = BASE;            // visible in test workers
  if (await up()) return;
  child = spawn("npx", ["next", "dev", "-p", String(PORT)], { stdio: "ignore", detached: true, env: { ...process.env } });
  for (const end = Date.now() + 120_000; Date.now() < end; await new Promise((r) => setTimeout(r, 1000)))
    if (await up()) return;
  throw new Error(`next dev did not come up on ${PORT}`);
}
export async function teardown() { if (child?.pid) try { process.kill(-child.pid, "SIGTERM"); } catch {} } // kill process group
